#!/usr/bin/env python3
# Applies manual corrections to the symbol files dumped from the OoT decomp ELF (see generate.us.rev0.toml).
# Usage: fixup_syms.py <syms.toml> <datasyms.toml>
import sys

# Sections whose names aren't valid in C identifiers generated by the recompiler.
SECTION_RENAMES = {
    "..makerom.ent": "..makerom_ent",
}

def main():
    if len(sys.argv) != 3:
        print(f"Usage: {sys.argv[0]} <syms.toml> <datasyms.toml>")
        sys.exit(1)

    for path in sys.argv[1:]:
        with open(path) as f:
            text = f.read()
        for old, new in SECTION_RENAMES.items():
            text = text.replace(f'name = "{old}"', f'name = "{new}"')
        with open(path, "w", newline="\n") as f:
            f.write(text)

if __name__ == "__main__":
    main()
